_MAX_BACKTEST_INPUT_SCAN = 1000
_MAX_BACKTEST_INPUT_LIMIT = 100
_MAX_CONFIG_BYTES = 1024 * 1024
_MAX_STATE_BYTES = 64 * 1024
_REPARSE_ATTRIBUTE = getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0x400)


def _is_link_or_reparse(path: Path) -> bool:
    try:
        info = path.lstat()
    except OSError:
        return True
    return stat.S_ISLNK(info.st_mode) or bool(
        getattr(info, "st_file_attributes", 0) & _REPARSE_ATTRIBUTE
    )


def _has_linked_component(path: Path, private_root: Path) -> bool:
    try:
        relative = path.relative_to(private_root)
    except ValueError:
        return True
    current = private_root
    for part in relative.parts:
        current = current / part
        if _is_link_or_reparse(current):
            return True
    return False


def _safe_private_directory(path: Path, private_root: Path) -> Path | None:
    if _has_linked_component(path, private_root):
        return None
    try:
        resolved = path.resolve(strict=True)
        if not resolved.is_dir() or not resolved.is_relative_to(private_root):
            return None
        return resolved
    except (OSError, ValueError):
        return None


def _safe_private_regular_file(path: Path, private_root: Path) -> Path | None:
    if _has_linked_component(path, private_root):
        return None
    try:
        return _private_file(path)
    except HTTPException:
        return None


def _bounded_text(value: object, maximum: int) -> str | None:
    if not isinstance(value, str) or not value or len(value) > maximum:
        return None
    if value != value.strip() or any(ord(char) < 32 or ord(char) == 127 for char in value):
        return None
    return value


def _backtest_input_config(config_path: Path) -> dict[str, object] | None:
    try:
        if config_path.stat().st_size > _MAX_CONFIG_BYTES:
            return None
        config = json.loads(config_path.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError):
        return None
    if not isinstance(config, dict):
        return None

    codes = config.get("codes")
    if (
        not isinstance(codes, list)
        or not codes
        or len(codes) > 100
        or any(_bounded_text(code, 64) is None for code in codes)
    ):
        return None
    start_date = config.get("start_date")
    end_date = config.get("end_date")
    if not isinstance(start_date, str) or not isinstance(end_date, str):
        return None
    try:
        if date.fromisoformat(start_date).isoformat() != start_date:
            return None
        if date.fromisoformat(end_date).isoformat() != end_date or start_date > end_date:
            return None
    except ValueError:
        return None
    source = _bounded_text(config.get("source"), 64)
    engine = _bounded_text(config.get("engine"), 64)
    if source is None or engine is None:
        return None
    return {
        "codes": codes,
        "start_date": start_date,
        "end_date": end_date,
        "source": source,
        "engine": engine,
    }


def _backtest_run_status(run_dir: Path, private_root: Path) -> str:
    state_path = _safe_private_regular_file(run_dir / "state.json", private_root)
    if state_path is not None:
        try:
            if state_path.stat().st_size <= _MAX_STATE_BYTES:
                state = json.loads(state_path.read_text(encoding="utf-8"))
                if isinstance(state, dict):
                    status = _bounded_text(state.get("status"), 32)
                    if status is not None:
                        return status
        except (OSError, UnicodeError, json.JSONDecodeError):
            pass

    equity_path = _safe_private_regular_file(
        run_dir / "artifacts" / "equity.csv", private_root
    )
    if equity_path is not None:
        try:
            if equity_path.stat().st_size > 0:
                return "success"
        except OSError:
            pass
    return "not_run"


def _list_backtest_inputs(limit: int) -> list[dict[str, object]]:
    try:
        private_root = get_runtime_root().resolve(strict=True)
        runs_path = get_runs_dir()
        if _is_link_or_reparse(runs_path):
            return []
        runs_root = runs_path.resolve(strict=True)
        if runs_root != private_root / "runs" or not runs_root.is_dir():
            return []
    except (OSError, ValueError):
        return []

    try:
        entries = []
        with os.scandir(runs_root) as iterator:
            for entry in iterator:
                if len(entries) >= _MAX_BACKTEST_INPUT_SCAN:
                    break
                entries.append(runs_root / entry.name)
    except OSError:
        return []

    run_candidates: list[tuple[int, Path]] = []
    for run_path in entries:
        if not _ID.fullmatch(run_path.name):
            continue
        run_dir = _safe_private_directory(run_path, private_root)
        if run_dir is None:
            continue
        try:
            modified_ns = run_dir.stat().st_mtime_ns
        except OSError:
            continue
        run_candidates.append((modified_ns, run_dir))

    run_candidates.sort(key=lambda pair: pair[0], reverse=True)
    items: list[dict[str, object]] = []
    for _modified_ns, run_dir in run_candidates:
        config_path = _safe_private_regular_file(
            run_dir / "config.json", private_root
        )
        code_path = _safe_private_regular_file(
            run_dir / "code" / "signal_engine.py", private_root
        )
        if config_path is None or code_path is None:
            continue
        config = _backtest_input_config(config_path)
        if config is None:
            continue
        items.append({
            "run_id": run_dir.name,
            "status": _backtest_run_status(run_dir, private_root),
            **config,
        })
        if len(items) >= limit:
            break
    return items


